  1274→    margin-top: calc(var(--spacing) * 6);
  1275→  }
  1276→  .typography details:not(.not-typography details) summary {
  1277→    cursor: pointer;
  1278→    font-weight: 600;
  1279→    margin-top: calc(var(--spacing) * 6);
  1280→    letter-spacing: var(--tracking-tight);
  1281→  }
  1282→  .typography details:not(.not-typography details) p:first-of-type {
  1283→    margin-top: calc(var(--spacing) * 2);
  1284→  }
  1285→  .typography mark:not(.not-typography mark) {
  1286→    background-color: var(--color-yellow-300);
  1287→  }
  1288→  .typography small:not(.not-typography small) {
  1289→    font-size: var(--text-xs);
  1290→    line-height: 1;
  1291→  }
  1292→
  1293→  @media (min-width: 1024px) {
  1294→    .typography h1:not(.not-typography h1) {
  1295→      font-size: var(--text-5xl);
  1296→      line-height: var(--text-5xl--line-height);
  1297→    }
  1298→  }
  1299→}
  1300→
  1301→@layer utils {
  1302→  .text-gradient {
  1303→    @apply bg-clip-text text-transparent;
  1304→  }
  1305→
  1306→  .bg-grid {
  1307→    --bg-grid-color: hsl(0 0% 100% / 0.1);
  1308→    background-color: transparent; /* Couleur de fond */
  1309→    background-image:
  1310→      linear-gradient(90deg, var(--bg-grid-color) 1px, transparent 1px),
  1311→      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
  1312→    background-size: 64px 64px; /* Taille de la grille */
  1313→  }
  1314→}
  1315→
  1316→/* ============================================
  1317→ * LANDING PAGE DARK TOKENS
  1318→ * Premium dark mode for landing page
  1319→ * ============================================ */
  1320→
  1321→/* Landing dark background variants */
  1322→:root {
  1323→  --landing-bg: oklch(0.12 0.01 270);
  1324→  --landing-card: oklch(0.15 0.01 270);
  1325→  --landing-border: oklch(0.22 0.01 270);
  1326→  --landing-muted: oklch(0.45 0.01 270);
  1327→
  1328→  /* Amber accents for landing */
  1329→  --landing-accent: oklch(0.83 0.16 85);
  1330→  --landing-accent-hover: oklch(0.88 0.18 85);
  1331→  --landing-orange: oklch(0.72 0.17 50);
  1332→
  1333→  /* Glow effects */
  1334→  --glow-amber: 0 0 20px oklch(0.83 0.16 85 / 0.3);
  1335→  --glow-amber-hover: 0 0 30px oklch(0.83 0.16 85 / 0.5);
  1336→
  1337→  /* Gradients */
  1338→  --gradient-cta: linear-gradient(
  1339→    to right,
  1340→    oklch(0.83 0.16 85),
  1341→    oklch(0.72 0.17 50)
  1342→  );
  1343→}
  1344→
  1345→/* Landing page specific classes */
  1346→.landing-dark {
  1347→  --background: oklch(0.12 0.01 270);
  1348→  --foreground: oklch(0.95 0.008 85);
  1349→  --card: oklch(0.15 0.01 270);
  1350→  --card-foreground: oklch(0.95 0.008 85);
  1351→  --border: oklch(0.22 0.01 270);
  1352→  --muted: oklch(0.18 0.01 270);
  1353→  --muted-foreground: oklch(0.65 0.01 270);
  1354→}
  1355→
  1356→/* Phone mockup shadows */
  1357→.shadow-device {
  1358→  box-shadow: var(--device-shadow);
  1359→}
  1360→
  1361→/* Floating animation */
  1362→.animate-float-slow {
  1363→  animation: float-slow 6s ease-in-out infinite;
  1364→}
  1365→
  1366→@keyframes float-slow {
  1367→  0%,
  1368→  100% {
  1369→    transform: translateY(0);
  1370→  }
  1371→  50% {
  1372→    transform: translateY(-20px);
  1373→  }
  1374→}
  1375→
  1376→/* Badge float animation */
  1377→.animate-badge-float {
  1378→  animation: badge-float 3s ease-in-out infinite;
  1379→}
  1380→
  1381→@keyframes badge-float {
  1382→  0%,
  1383→  100% {
  1384→    transform: translateY(0) rotate(-2deg);
  1385→  }
  1386→  50% {
  1387→    transform: translateY(-10px) rotate(2deg);
  1388→  }
  1389→}
  1390→
  1391→/* Glow button effect */
  1392→.glow-button {
  1393→  box-shadow: var(--glow-amber);
  1394→  transition:
  1395→    box-shadow 0.3s ease,
  1396→    transform 0.3s ease;
  1397→}
  1398→
  1399→.glow-button:hover {
  1400→  box-shadow: var(--glow-amber-hover);
  1401→  transform: translateY(-2px);
  1402→}
  1403→
  1404→/* Dot pattern for CTA */
  1405→.dot-pattern-cta {
  1406→  background-image: radial-gradient(rgba(0, 0, 0, 0.15) 1px, transparent 1px);
  1407→  background-size: 16px 16px;
  1408→}
  1409→
  1410→/* Bento grid item hover */
  1411→.bento-item {
  1412→  transition:
  1413→    transform 0.3s ease,
  1414→    border-color 0.3s ease;
  1415→}
  1416→
  1417→.bento-item:hover {
  1418→  transform: translateY(-4px);
  1419→  border-color: oklch(0.35 0.01 270);
  1420→}
  1421→
  1422→/* Stagger animation for cards */
  1423→.stagger-item {
  1424→  animation: stagger-fade-in 0.5s ease forwards;
  1425→  opacity: 0;
  1426→}
  1427→
  1428→.stagger-item:nth-child(1) {
  1429→  animation-delay: 0.1s;
  1430→}
  1431→.stagger-item:nth-child(2) {
  1432→  animation-delay: 0.2s;
  1433→}
  1434→.stagger-item:nth-child(3) {
  1435→  animation-delay: 0.3s;
  1436→}
  1437→.stagger-item:nth-child(4) {
  1438→  animation-delay: 0.4s;
  1439→}
  1440→
  1441→/* Other styles */
  1442→
  1443→.citation {
  1444→  position: relative;
  1445→  display: inline-block;
  1446→  padding: 4px;
  1447→  border-radius: 0.5rem;
  1448→  color: var(--foreground);
  1449→  font-style: italic;
  1450→  --gap: -16px;
  1451→}
  1452→
  1453→.citation::before {
  1454→  content: "“";
  1455→  font-size: 3rem;
  1456→  position: absolute;
  1457→  top: -12px;
  1458→  left: -12px;
  1459→  line-height: 1;
  1460→  color: hsl(var(--primary));
  1461→}
  1462→
  1463→.citation::after {
  1464→  content: "”";
  1465→  font-size: 3rem;
  1466→  position: absolute;
  1467→  bottom: -16px;
  1468→  right: -4px;
  1469→  line-height: 1;
  1470→  color: hsl(var(--primary));
  1471→}
  1472→
  1473→.citation strong {
  1474→  font-weight: 700;
  1475→  background: hsl(var(--primary) / 0.5);
  1476→  display: inline;
  1477→  padding: 2px;
  1478→  margin: -2px;
  1479→}
  1480→
  1481→.dot-pattern {
  1482→  background-color: var(--dot-background);
  1483→  opacity: 0.8;
  1484→  background-image: radial-gradient(
  1485→    var(--dot-color) 0.5px,
  1486→    var(--dot-background) 0.5px
  1487→  );
  1488→  background-size: var(--size, 10px) var(--size, 10px);
  1489→}
  1490→
  1491→html.dark .shiki,
  1492→html.dark .shiki span {
  1493→  color: var(--shiki-dark) !important;
  1494→  background-color: var(--shiki-dark-bg) !important;
  1495→  /* Optional, if you also want font styles */
  1496→  font-style: var(--shiki-dark-font-style) !important;
