@import "tailwindcss";
@plugin "tailwindcss-animate";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-success-foreground: var(--success-foreground);
  --color-success: var(--success);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning: var(--warning);
  --color-info-foreground: var(--info-foreground);
  --color-info: var(--info);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);

  /* EggscuseMe Freshness Colors */
  --color-fresh-extra: var(--fresh-extra);
  --color-fresh-extra-foreground: var(--fresh-extra-foreground);
  --color-fresh: var(--fresh);
  --color-fresh-foreground: var(--fresh-foreground);
  --color-fresh-cook: var(--fresh-cook);
  --color-fresh-cook-foreground: var(--fresh-cook-foreground);
  --color-expired: var(--expired);
  --color-expired-foreground: var(--expired-foreground);

  /* Mobile Navigation Colors */
  --color-nav-bg: var(--nav-bg);
  --color-nav-border: var(--nav-border);
  --color-nav-active: var(--nav-active);
  --color-nav-active-foreground: var(--nav-active-foreground);
  --color-nav-inactive: var(--nav-inactive);
  /* Radius tokens */
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: var(--radius-soft);
  --radius-3xl: var(--radius-card);
  --radius-full: var(--radius-button);

  /* Neubrutalism tokens */
  --shadow-neu: var(--shadow-hard);
  --shadow-neu-hover: var(--shadow-hard-hover);
  --shadow-neu-lg: var(--shadow-hard-lg);
  --border-neu: var(--border-width);

  /* Font tokens */
  --font-heading: var(--font-heading);
  --font-body: var(--font-body);

  /* ============================================
   * MOBILE-FIRST TOKENS
   * ============================================ */

  /* Spacing mobile */
  --space-safe-bottom: env(safe-area-inset-bottom, 0px);
  --space-safe-top: env(safe-area-inset-top, 0px);
  --nav-height: 80px;
  --header-height: 60px;
  --fab-size: 56px;

  /* Z-index layers */
  --z-base: 0;
  --z-dropdown: 10;
  --z-sticky: 20;
  --z-fab: 40;
  --z-nav: 50;
  --z-modal-backdrop: 90;
  --z-modal: 100;
  --z-toast: 200;

  /* Timing functions */
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: cubic-bezier(0.175, 0.885, 0.32, 1.275);
  --ease-out-back: cubic-bezier(0.34, 1.3, 0.64, 1);

  /* Durations */
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
  --duration-slower: 600ms;

  /* Shadows mobile */
  --shadow-fab: 0 4px 14px rgba(0, 0, 0, 0.15);
  --shadow-modal: 0 -4px 24px rgba(0, 0, 0, 0.12);
  --shadow-card-active: 0 8px 24px rgba(0, 0, 0, 0.15);
  --shadow-glow-primary: 0 0 20px oklch(0.85 0.18 85 / 0.4);

  /* ============================================
   * ENHANCED MOBILE-FIRST TOKENS
   * ============================================ */

  /* Touch targets (WCAG compliance) */
  --touch-target-min: 44px;
  --touch-target-comfortable: 48px;
  --touch-target-large: 56px;

  /* Mobile spacing */
  --space-page-x: 8px;
  --space-page-y: 8px;
  --space-section: 24px;
  --space-card-padding: 12px;
  --space-card-gap: 12px;

  /* Navigation tokens */
  --nav-height-mobile: 72px;
  --header-height-mobile: 56px;

  /* Transition tokens */
  --transition-page: 300ms var(--ease-smooth);
  --transition-sheet: 400ms var(--ease-spring);
  --transition-micro: 150ms var(--ease-smooth);
  --transition-touch: 100ms var(--ease-smooth);

  /* Glass morphism */
  --glass-bg: oklch(0.99 0.008 85 / 0.8);
  --glass-bg-dark: oklch(0.18 0.02 60 / 0.85);
  --glass-border: oklch(0.9 0.02 85 / 0.5);
  --glass-border-dark: oklch(0.32 0.02 60 / 0.5);

  /* Radius mobile */
  --radius-modal: 28px;
  --radius-sheet: 24px;
  --radius-fab: 9999px;
  --radius-chip: 12px;
  --radius-pill: 9999px;

  /* ============================================
   * STICKER ILLUSTRATION TOKENS
   * Consistent style for all mascot/illustrations
   * ============================================ */

  /* Sticker stroke & fill */
  --sticker-stroke: #1c1917;
  --sticker-stroke-width: 2px;
  --sticker-fill-egg: #fdfbf7;
  --sticker-fill-white: #ffffff;
  --sticker-shadow: drop-shadow(0 2px 4px rgb(0 0 0 / 0.1));
  --sticker-shadow-lg: drop-shadow(0 4px 8px rgb(0 0 0 / 0.15));

  /* Illustration brand colors */
  --illu-brand: #fbbf24;
  --illu-brand-dark: #d97706;
  --illu-fresh-extra: var(--fresh-extra);
  --illu-fresh: var(--fresh);
  --illu-fresh-cook: var(--fresh-cook);
  --illu-expired: #ef4444;

  /* Accessory & scene colors */
  --illu-wood: #92400e;
  --illu-wood-light: #b45309;
  --illu-metal: #6b7280;
  --illu-metal-light: #9ca3af;
  --illu-plastic: #3b82f6;
  --illu-glass: #e0f2fe;
  --illu-fridge: #f1f5f9;
  --illu-fridge-dark: #cbd5e1;

  /* Blush & expression colors */
  --illu-blush: #ffb6c1;
  --illu-tear: #87ceeb;
  --illu-sweat: #87ceeb;
  --illu-sparkle: #fcd34d;

  /* Party/confetti colors */
  --illu-confetti-1: #fbbf24;
  --illu-confetti-2: #34d399;
  --illu-confetti-3: #f472b6;
  --illu-confetti-4: #60a5fa;
  --illu-confetti-5: #a78bfa;

  /* Animations */
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
  --animate-bounce-subtle: bounce-subtle 0.5s ease-in-out;
  --animate-wobble: wobble 0.5s ease-in-out;
  --animate-float: float 3s ease-in-out infinite;
  --animate-bounce-excited: bounce-excited 0.6s var(--ease-bounce);
  --animate-steam-rise: steam-rise 2s ease-out infinite;
  --animate-wave-hand: wave-hand 1s ease-in-out infinite;
  --animate-confetti-pop: confetti-pop 0.5s var(--ease-out-back);
  --animate-shine-crown: shine-crown 2s ease-in-out infinite;
  --animate-glow-pulse: glow-pulse 2s ease-in-out infinite;
  --animate-pulse-ring: pulse-ring 1.5s ease-in-out infinite;
  --animate-shake-alert: shake-alert 0.5s ease-in-out;
  --animate-thinking-dots: thinking-dots 1.5s ease-in-out infinite;
  --animate-slide-up: slide-up 0.3s var(--ease-spring);
  --animate-fade-scale: fade-scale 0.2s var(--ease-smooth);
  --animate-ripple: ripple 0.6s ease-out;

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }

  /* Mascot Animations */
  @keyframes bounce-subtle {
    0%,
    100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-5px);
    }
  }

  @keyframes wobble {
    0%,
    100% {
      transform: rotate(0deg);
    }
    25% {
      transform: rotate(-3deg);
    }
    75% {
      transform: rotate(3deg);
    }
  }

  @keyframes float {
    0%,
    100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-10px);
    }
  }

  @keyframes crack {
    0% {
      transform: scale(1);
    }
    50% {
      transform: scale(1.05);
    }
    100% {
      transform: scale(1);
    }
  }

  @keyframes bubble {
    0% {
      transform: translateY(0) scale(1);
      opacity: 0.7;
    }
    100% {
      transform: translateY(-20px) scale(0.5);
      opacity: 0;
    }
  }

  /* ============================================
   * NEW MASCOT ANIMATIONS
   * ============================================ */

  @keyframes bounce-excited {
    0%,
    100% {
      transform: translateY(0) scale(1);
    }
    25% {
      transform: translateY(-15px) scale(1.05);
    }
    50% {
      transform: translateY(-8px) scale(1.02);
    }
    75% {
      transform: translateY(-12px) scale(1.03);
    }
  }

  @keyframes steam-rise {
    0% {
      transform: translateY(0) scaleY(1);
      opacity: 0.6;
    }
    50% {
      opacity: 0.8;
    }
    100% {
      transform: translateY(-25px) scaleY(1.5);
      opacity: 0;
    }
  }

  @keyframes wave-hand {
    0%,
    100% {
      transform: rotate(0deg);
    }
    20% {
      transform: rotate(20deg);
    }
    40% {
      transform: rotate(-10deg);
    }
    60% {
      transform: rotate(15deg);
    }
    80% {
      transform: rotate(-5deg);
    }
  }

  @keyframes confetti-pop {
    0% {
      transform: scale(0) rotate(0deg);
      opacity: 1;
    }
    50% {
      transform: scale(1.2) rotate(180deg);
    }
    100% {
      transform: scale(1) rotate(360deg);
      opacity: 0;
    }
  }

  @keyframes shine-crown {
    0%,
    100% {
      filter: brightness(1) drop-shadow(0 0 0px oklch(0.85 0.18 85));
    }
    50% {
      filter: brightness(1.3) drop-shadow(0 0 8px oklch(0.85 0.18 85));
    }
  }

  @keyframes glow-pulse {
    0%,
    100% {
      box-shadow: 0 0 10px var(--fresh-extra);
      filter: brightness(1);
    }
    50% {
      box-shadow: 0 0 25px var(--fresh-extra);
      filter: brightness(1.1);
    }
  }

  @keyframes pulse-ring {
    0% {
      transform: scale(1);
      opacity: 1;
    }
    50% {
      transform: scale(1.1);
      opacity: 0.8;
    }
    100% {
      transform: scale(1);
      opacity: 1;
    }
  }

  @keyframes shake-alert {
    0%,
    100% {
      transform: translateX(0);
    }
    10%,
    30%,
    50%,
    70%,
    90% {
      transform: translateX(-4px);
    }
    20%,
    40%,
    60%,
    80% {
      transform: translateX(4px);
    }
  }

  @keyframes thinking-dots {
    0%,
    100% {
      opacity: 0.3;
    }
    50% {
      opacity: 1;
    }
  }

  /* ============================================
   * UI ANIMATIONS
   * ============================================ */

  @keyframes slide-up {
    from {
      transform: translateY(100%);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  @keyframes slide-down {
    from {
      transform: translateY(-20px);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  @keyframes fade-scale {
    from {
      transform: scale(0.95);
      opacity: 0;
    }
    to {
      transform: scale(1);
      opacity: 1;
    }
  }

  @keyframes ripple {
    0% {
      transform: scale(0);
      opacity: 0.5;
    }
    100% {
      transform: scale(2.5);
      opacity: 0;
    }
  }

  @keyframes stagger-fade-in {
    from {
      transform: translateY(10px);
      opacity: 0;
    }
    to {
      transform: translateY(0);
      opacity: 1;
    }
  }

  @keyframes progress-fill {
    from {
      stroke-dashoffset: var(--progress-circumference);
    }
    to {
      stroke-dashoffset: var(--progress-offset);
    }
  }

  @keyframes number-count {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes float-cape {
    0%,
    100% {
      transform: translateY(0) rotate(-2deg);
    }
    25% {
      transform: translateY(-8px) rotate(0deg);
    }
    50% {
      transform: translateY(-5px) rotate(2deg);
    }
    75% {
      transform: translateY(-10px) rotate(0deg);
    }
  }

  @keyframes magnify-pulse {
    0%,
    100% {
      transform: scale(1) rotate(0deg);
    }
    25% {
      transform: scale(1.1) rotate(-5deg);
    }
    75% {
      transform: scale(1.05) rotate(5deg);
    }
  }

  /* ============================================
   * NEO-SOFT-BRUTALISME DESIGN SYSTEM
   * Style: Rounded corners + Thick borders + Hard shadows
   * ============================================ */

  /* Neo colors mapping */
  --color-neo-bg: var(--neo-bg);
  --color-neo-card: var(--neo-card);
  --color-neo-text: var(--neo-text);
  --color-neo-text-muted: var(--neo-text-muted);
  --color-neo-border: var(--neo-border);
  --color-neo-accent: var(--neo-accent);
  --color-neo-accent-foreground: var(--neo-accent-foreground);
  --color-neo-input: var(--neo-input);

  /* Device mockup (landing) */
  --color-device-bg: var(--device-bg);
  --color-device-bezel: var(--device-bezel);
  --color-device-notch: var(--device-notch);
  --shadow-device: var(--device-shadow);

  /* Neo radius tokens */
  --radius-neo-sm: 0.75rem;
  --radius-neo-md: 1rem;
  --radius-neo-lg: 1.25rem;
  --radius-neo-xl: 1.5rem;
  --radius-neo-2xl: 2rem;
  --radius-neo-3xl: 2.5rem;

  /* Neo border tokens */
  --border-neo: 2px;
  --border-neo-lg: 3px;

  /* Neo shadow tokens */
  --shadow-neo-sm: 2px 2px 0px var(--neo-shadow-color);
  --shadow-neo-md: 4px 4px 0px var(--neo-shadow-color);
  --shadow-neo-lg: 6px 6px 0px var(--neo-shadow-color);
  --shadow-neo-xl: 8px 8px 0px var(--neo-shadow-color);
  --shadow-neo-hover: 2px 2px 0px var(--neo-shadow-color);
  --shadow-neo-active: 0px 0px 0px transparent;

  /* Neo transition tokens */
  --duration-neo: 200ms;
  --ease-neo: ease;
  --transition-neo: var(--duration-neo) var(--ease-neo);

  /* Neo animations */
  --animate-neo-press: neo-press 100ms ease;
  --animate-neo-bounce-in: neo-bounce-in 300ms var(--ease-bounce);
  --animate-neo-slide-up: neo-slide-up 400ms var(--ease-spring);
  --animate-neo-wiggle: neo-wiggle 400ms var(--ease-bounce);
  --animate-neo-pop: neo-pop 200ms var(--ease-bounce);

  /* Neo keyframes */
  @keyframes neo-press {
    0% {
      transform: translate(0, 0);
    }
    100% {
      transform: translate(4px, 4px);
    }
  }

  @keyframes neo-bounce-in {
    0% {
      transform: scale(0.9);
      opacity: 0;
    }
    50% {
      transform: scale(1.05);
    }
    100% {
      transform: scale(1);
      opacity: 1;
    }
  }

  @keyframes neo-slide-up {
    from {
      transform: translateY(100%) rotate(5deg);
    }
    to {
      transform: translateY(0) rotate(0);
    }
  }

  @keyframes neo-wiggle {
    0%,
    100% {
      transform: rotate(0deg);
    }
    25% {
      transform: rotate(-3deg);
    }
    75% {
      transform: rotate(3deg);
    }
  }

  @keyframes neo-pop {
    0% {
      transform: scale(0.8);
      opacity: 0;
    }
    60% {
      transform: scale(1.1);
    }
    100% {
      transform: scale(1);
      opacity: 1;
    }
  }

  @keyframes neo-check-draw {
    from {
      stroke-dashoffset: 24;
    }
    to {
      stroke-dashoffset: 0;
    }
  }
}

:root,
.force-light-theme {
  /* ============================================
