  /* Sidebar - Cream tones */
  --sidebar: oklch(0.98 0.008 85); /* Light eggshell */
  --sidebar-foreground: oklch(0.25 0.02 270);
  --sidebar-primary: oklch(0.85 0.18 85); /* Yolk yellow */
