}
```

**DemoPhoneContainer.tsx** - Conteneur avec thème inversé :

```tsx
"use client";

import { cn } from "@/lib/utils";
import type { ReactNode } from "react";

type DemoPhoneContainerProps = {
  children: ReactNode;
  className?: string;
};

/**
 * Container that applies the inverted theme for the demo phone.
 * When the site is in dark mode, this container shows light mode, and vice versa.
 */
export function DemoPhoneContainer({
  children,
  className,
}: DemoPhoneContainerProps) {
  return (
    <div
      className={cn(
        "demo-phone-container",
        "bg-neo-bg text-neo-text",
        "flex h-full w-full flex-col font-sans",
        className,
      )}
    >
      {children}
    </div>
  );
}
```

### 4. DÉPENDANCES UTILISÉES

#### **Librairies npm :**
- **`motion`** v12.23.16 - Pour les animations scroll (Framer Motion successor)
  - `useScroll()` - Détecte le scroll au sein d'une zone
  - `useTransform()` - Transforme les valeurs de scroll en animations
  - `motion.div` - Composant div animé

#### **Tailwind CSS Classes personnalisées :**
- `shadow-device` - Ombre projetée du device
- `bg-device-bg` - Couleur de fond du device (noir dark)
- `bg-device-bezel` - Couleur du biseau (bordure device)
- `bg-device-notch` - Couleur de l'enoche dynamique
- `bg-background` - Couleur du background de l'écran

#### **Styles CSS (globals.css - lignes 556-560 et 806-811) :**

```css
/* Device mockup (landing) */
--color-device-bg: var(--device-bg);
--color-device-bezel: var(--device-bezel);
--color-device-notch: var(--device-notch);
--shadow-device: var(--device-shadow);

/* Valeurs définies pour light mode */
--device-bg: oklch(0.12 0.01 270);              /* Noir foncé */
--device-bezel: oklch(0.25 0.01 270);           /* Gris foncé */
--device-notch: oklch(0.1 0 0);                 /* Noir pur */
--device-shadow: 0 50px 100px -20px hsl(0 0% 0% / 0.3), 0 30px 60px -30px hsl(0 0% 0% / 0.4);
```

#### **Images/Assets :**
Aucune image externe - le mockup est entièrement construit en CSS et HTML.

### 5. ARCHITECTURE INTERNE

```
PhoneMockup (composant conteneur avec parallax)
├─ Device Shadow (gradient blur)
├─ Device Frame (bordure noire)
│  ├─ Inner Bezel (bordure fine grise)
│  ├─ Screen Container (écran blanc/content)
│  │  ├─ Dynamic Island (enoche noire)
│  │  │  └─ Camera (petit point bleu)
│  │  ├─ Screen Content (children - affiche DemoPhoneContent)
│  │  └─ Home Indicator (barre inférieure)
│  └─ Side Buttons (4 boutons côtés)
```

### 6. COMMENT IL EST UTILISÉ

**Dans HeroSection.tsx (lignes 142-144) :**

```tsx
{/* Phone */}
<PhoneMockup className="relative z-10">
  <PhoneAppPreview />
</PhoneMockup>
```

Le composant `PhoneMockup` :
1. Enveloppe le contenu (`PhoneAppPreview`)
2. Ajoute l'effet parallax au scroll (rotation et décalage Y)
3. Simule un iPhone 14 Pro avec dimensions réalistes (393x852px scaled 0.95)
4. Affiche dynamiquement le contenu de la démo qui change selon les onglets (Fridge, Timer, Recipes, Stats)

### 7. FEATURES IMPORTANTES

- **Responsive**: Utilise `relative mx-auto` pour centrer l'appareil
- **Thème inversé**: La démo affiche le thème opposé du site (light/dark inversion)
- **Animations**: Parallax au scroll + rotation basée sur la position de scroll
- **Réaliste**: Inclut Dynamic Island, boutons latéraux, home indicator, ombre projection
- **Dimensions iPhone 14 Pro**: 393x852px (scaled à 0.95)

